package main

import (
	"flag"
	"fmt"
	"strings"

	"example.com/tool/parse"
)

func main() {
	legacy := flag.Bool("legacy", false, "read the old format")
	flag.Parse()
	for _, a := range flag.Args() {
		if *legacy {
			fmt.Println(parse.ParseLegacy(a))
			continue
		}
		fmt.Println(strings.Split(a, ","))
	}
}

